import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createAcceptanceHarness, assertOk, assertError} from '../support/core-harness.mjs';
import {LOG_CATEGORIES, defaultLogPolicy, logCategory, logCountSpecs, logDecision, parseLogPolicy, readLogPolicy} from '../../../gas/src/domain/policies/LogPolicy.js';
